// Package postgres implements run.Repository on PostgreSQL with code
// generated by sqlc from queries/ (run `make sqlc` after changing them).
package postgres

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/jrgomesdev/miner/internal/execution/run"
	"github.com/jrgomesdev/miner/internal/execution/run/postgres/sqlcdb"
	"github.com/jrgomesdev/miner/internal/task"
)

const codeUniqueViolation = "23505"

// Repository stores runs in PostgreSQL.
type Repository struct {
	pool *pgxpool.Pool
	q    *sqlcdb.Queries
}

// NewRepository returns a repository that uses pool.
func NewRepository(pool *pgxpool.Pool) *Repository {
	return &Repository{pool: pool, q: sqlcdb.New(pool)}
}

var _ run.Repository = (*Repository)(nil)

func (r *Repository) Start(ctx context.Context, rn run.Run) error {
	return r.inTx(ctx, func(q *sqlcdb.Queries) error {
		status, err := q.LockTaskStatus(ctx, rn.TaskID)
		if err != nil {
			return notFound(err)
		}
		if task.Status(status) != task.StatusReady {
			return fmt.Errorf("%w: task is %s, not ready", task.ErrInvalidTransition, status)
		}
		err = q.InsertRun(ctx, sqlcdb.InsertRunParams{
			ID:         rn.ID,
			TaskID:     rn.TaskID,
			Status:     string(run.StatusQueued),
			Agent:      rn.Agent,
			Model:      rn.Model,
			Effort:     rn.Effort,
			Runner:     rn.Runner,
			RepoUrl:    rn.RepoURL,
			BaseBranch: rn.BaseBranch,
			Branch:     rn.Branch,
			CreatedAt:  rn.CreatedAt,
		})
		var pgErr *pgconn.PgError
		if errors.As(err, &pgErr) && pgErr.Code == codeUniqueViolation {
			return fmt.Errorf("%w: task already has an active run", task.ErrConflict)
		}
		if err != nil {
			return fmt.Errorf("insert run: %w", err)
		}
		return moveTask(ctx, q, rn.TaskID, task.StatusReady, task.StatusInProgress, rn.CreatedAt)
	})
}

func (r *Repository) Abort(ctx context.Context, id uuid.UUID) error {
	return r.inTx(ctx, func(q *sqlcdb.Queries) error {
		taskID, err := q.DeleteQueuedRun(ctx, id)
		if err != nil {
			return notFound(err)
		}
		return moveTask(ctx, q, taskID, task.StatusInProgress, task.StatusReady, time.Now().UTC())
	})
}

func (r *Repository) Get(ctx context.Context, id uuid.UUID) (run.Run, error) {
	row, err := r.q.GetRun(ctx, id)
	if err != nil {
		return run.Run{}, notFound(err)
	}
	return toRun(row), nil
}

func (r *Repository) ListByTask(ctx context.Context, taskID uuid.UUID) ([]run.Run, error) {
	rows, err := r.q.ListRunsByTask(ctx, taskID)
	if err != nil {
		return nil, fmt.Errorf("list runs: %w", err)
	}
	out := make([]run.Run, 0, len(rows))
	for _, row := range rows {
		// The listing leaves the diff out; the other columns match a full row.
		out = append(out, toRun(sqlcdb.Run{
			ID: row.ID, TaskID: row.TaskID, Status: row.Status,
			Agent: row.Agent, Model: row.Model, Effort: row.Effort, Runner: row.Runner,
			RepoUrl: row.RepoUrl, BaseBranch: row.BaseBranch, Branch: row.Branch,
			AuthMethod: row.AuthMethod, EffectiveModel: row.EffectiveModel, CostUsd: row.CostUsd,
			NumTurns: row.NumTurns, ExitCode: row.ExitCode, Error: row.Error,
			CancelRequestedAt: row.CancelRequestedAt, CreatedAt: row.CreatedAt,
			StartedAt: row.StartedAt, FinishedAt: row.FinishedAt,
		}))
	}
	return out, nil
}

func (r *Repository) Active(ctx context.Context, taskID uuid.UUID) (run.Run, bool, error) {
	row, err := r.q.GetActiveRun(ctx, taskID)
	if errors.Is(err, pgx.ErrNoRows) {
		return run.Run{}, false, nil
	}
	if err != nil {
		return run.Run{}, false, fmt.Errorf("get active run: %w", err)
	}
	return toRun(row), true, nil
}

func (r *Repository) MarkRunning(ctx context.Context, id uuid.UUID, at time.Time, authMethod string) (bool, error) {
	n, err := r.q.MarkRunning(ctx, sqlcdb.MarkRunningParams{ID: id, StartedAt: &at, AuthMethod: &authMethod})
	if err != nil {
		return false, fmt.Errorf("mark run running: %w", err)
	}
	return n == 1, nil
}

func (r *Repository) RequestCancel(ctx context.Context, id uuid.UUID, at time.Time) (bool, error) {
	n, err := r.q.RequestCancel(ctx, sqlcdb.RequestCancelParams{ID: id, CancelRequestedAt: &at})
	if err != nil {
		return false, fmt.Errorf("request run cancellation: %w", err)
	}
	return n == 1, nil
}

func (r *Repository) Finish(ctx context.Context, id uuid.UUID, status run.Status, res run.Result, at time.Time) (bool, error) {
	finished := false
	err := r.inTx(ctx, func(q *sqlcdb.Queries) error {
		taskID, err := q.FinishRun(ctx, sqlcdb.FinishRunParams{
			ID:             id,
			Status:         string(status),
			EffectiveModel: res.EffectiveModel,
			CostUsd:        res.CostUSD,
			NumTurns:       res.NumTurns,
			ExitCode:       res.ExitCode,
			Error:          res.Error,
			Diff:           res.Diff,
			FinishedAt:     &at,
		})
		if errors.Is(err, pgx.ErrNoRows) {
			return nil
		}
		if err != nil {
			return fmt.Errorf("finish run: %w", err)
		}
		finished = true
		// A task that left in_progress (cancelled, for example) keeps its status.
		_, err = q.MoveTask(ctx, sqlcdb.MoveTaskParams{
			ID: taskID, From: string(task.StatusInProgress), To: string(run.TaskStatusAfter(status)), UpdatedAt: at,
		})
		return err
	})
	return finished, err
}

func (r *Repository) ListRunning(ctx context.Context) ([]run.Run, error) {
	rows, err := r.q.ListRunningRuns(ctx)
	if err != nil {
		return nil, fmt.Errorf("list running runs: %w", err)
	}
	out := make([]run.Run, 0, len(rows))
	for _, row := range rows {
		out = append(out, toRun(row))
	}
	return out, nil
}

// inTx runs fn in a transaction, committing only when fn succeeds.
func (r *Repository) inTx(ctx context.Context, fn func(*sqlcdb.Queries) error) error {
	tx, err := r.pool.Begin(ctx)
	if err != nil {
		return fmt.Errorf("begin transaction: %w", err)
	}
	defer func() { _ = tx.Rollback(ctx) }()
	if err := fn(r.q.WithTx(tx)); err != nil {
		return err
	}
	if err := tx.Commit(ctx); err != nil {
		return fmt.Errorf("commit transaction: %w", err)
	}
	return nil
}

// moveTask changes the status of a task that must be in from.
func moveTask(ctx context.Context, q *sqlcdb.Queries, id uuid.UUID, from, to task.Status, at time.Time) error {
	n, err := q.MoveTask(ctx, sqlcdb.MoveTaskParams{ID: id, From: string(from), To: string(to), UpdatedAt: at})
	if err != nil {
		return fmt.Errorf("move task: %w", err)
	}
	if n == 0 {
		return fmt.Errorf("%w: task is not %s", task.ErrInvalidTransition, from)
	}
	return nil
}

func toRun(row sqlcdb.Run) run.Run {
	return run.Run{
		ID:     row.ID,
		TaskID: row.TaskID,
		Status: run.Status(row.Status),
		Snapshot: run.Snapshot{
			Agent:      row.Agent,
			Model:      row.Model,
			Effort:     row.Effort,
			Runner:     row.Runner,
			RepoURL:    row.RepoUrl,
			BaseBranch: row.BaseBranch,
			Branch:     row.Branch,
		},
		AuthMethod: row.AuthMethod,
		Result: run.Result{
			EffectiveModel: row.EffectiveModel,
			CostUSD:        row.CostUsd,
			NumTurns:       row.NumTurns,
			ExitCode:       row.ExitCode,
			Error:          row.Error,
			Diff:           row.Diff,
		},
		CancelRequestedAt: row.CancelRequestedAt,
		CreatedAt:         row.CreatedAt,
		StartedAt:         row.StartedAt,
		FinishedAt:        row.FinishedAt,
	}
}

func notFound(err error) error {
	if errors.Is(err, pgx.ErrNoRows) {
		return task.ErrNotFound
	}
	return err
}
